# -*- coding: utf-8 -*-
"""C1427: distinguish, extinguish and instinct; do not invent a single semantic chain."""
import json
from pathlib import Path
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def S(w):return 'https://www.etymonline.com/word/'+w
def M(w):return 'https://www.merriam-webster.com/dictionary/'+w
def O(w):return 'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
def A(h,w,m):return h+[[w,m]]
D=[['拉丁 distinguere〔dis- + -stinguere〕','分开、标出区别；更古老的刺、推等分析有分歧']]
DW=D+[['法语 distinguer／词干 distinguiss-，也有直接拉丁借入分析','辨别、区分'],['中古英语 distingwen 等 → 现代 distinguish','辨别；使出众；现代词尾受 -ish 类形式影响']]
DT=D+[['拉丁分词 distinctus','已区分开的、清楚的'],['中古英语 distinct〔另经古法语 distincter、旧动词 distincten 分析〕','分别的、能清楚辨认的'],['现代英语 distinct','不同的；清楚明显的']]
DV=D+[['拉丁分词词干 distinct- → 中世纪拉丁 distinctivus','能够区分、标出差异的'],['古法语 distinctif／直接借入 → 英语 distinctive','有辨识度的、有特色的']]
IND=D+[['拉丁 in- + distinctus → indistinctus','未区分开的、含混的'],['法语 indistinct／直接拉丁借入 → 英语 indistinct','不清楚、难辨认的']]
X=[['拉丁 exstinguere／extinguere','扑灭、消除；ex- 表示向外、消去'],['拉丁动词借入并以英语 -ish 类词尾适应 → extinguish','把火熄掉；使希望等消失']]
I=[['拉丁 instinguere〔in- + stinguere〕','激起、驱使；有向内刺激的形象'],['拉丁 instinctus','推动、冲动；动词分词的名词化'],['古法语 instinct／直接拉丁借入 → 英语 instinct','内在驱动；本能、直觉']]
IV=I[:2]+[['拉丁词干 instinct- 与 -ive；也可对应英语 instinct + -ive','形成描述本能、自然反应的形容词'],['英语 instinctive','出于本能或不假思索的']]
W=[
E('distinguish','/dɪˈstɪŋɡwɪʃ/','区分、辨别；看清、听清；使出众','把容易混在一起的东西认出来：两种声音、真假文件，或某人身上别人没有的特点。','拉丁 distinguere 表示分开、作区分，经法语 distinguer 等进入英语；dis- 是“分开”。第二部分古义有刺、推等分析，不能把“刺一下就聪明”当真实词史。',DW,'distinguish A from B 是把 A 和 B 区分开；distinguish between A and B 也是辨别二者。distinguish yourself 则是凭表现脱颖而出。','distinguish A from B；distinguish between two things；distinguish yourself。','identify 偏认出是什么；distinguish 偏看出差别或从背景里辨出。不同东西可以被识别，却仍难说出彼此区别。',('Can you distinguish the original from the copy?','你能分辨原件和复制件吗？'),('Her careful listening distinguishes her from many other interviewers.','她认真倾听的习惯让她在许多采访者中显得与众不同。'),sources=[S('distinguish'),K('distinguish'),M('distinguish')]),
E('distinguished','/dɪˈstɪŋɡwɪʃt/','杰出的、受尊敬的；气度不凡的；已区分的','一个人从人群里“显出来”，是因为成就、声望，或举止有气度。常见形容词义带赞许，不只是与别人不一样。','distinguish + -ed，过去分词及形容词；末尾 /ʃ/ 后 -ed 读 /t/。在被动句中也可能只是“被区分”，要看上下文。',A(DW,'英语 distinguish + -ed → distinguished','已被区分；引申因成就或气质而出众'),'a distinguished scientist 是有成就、有声望的科学家；a distinguished appearance 是仪表不凡。be distinguished by something 说某种特点让其突出。','a distinguished career；a distinguished guest；look distinguished；be distinguished by。','distinctive 是有特色、容易识别，不一定优秀；distinguished 通常带成就或气度上的肯定。',('The lecture was given by a distinguished historian.','讲座由一位享有声望的历史学家主讲。'),('His silver hair and calm manner gave him a distinguished appearance.','银发和沉稳的举止让他显得气度不凡。'),sources=[K('distinguished'),S('distinguish'),O('distinguished')]),
E('distinguishable','/dɪˈstɪŋɡwɪʃəbəl/','可以区分的；可以辨认的','差异足够明显，眼睛、耳朵或分析方法能够把它们分开。它说的是“能不能辨”，不保证辨起来轻松。','distinguish + -able，英语形容词，表示能够被区分或察觉。',A(DW,'英语 distinguish + -able → distinguishable','能看出、听出或判断出区别的'),'distinguishable from 是与某物可以区分；barely distinguishable 是勉强能辨。远处一个形状从背景里显出来，也可以这样说。','clearly distinguishable；barely distinguishable；distinguishable from。','different 说实际不同；distinguishable 说这种不同能够被辨认。两个物体不同，却可能肉眼分不出来。',('The two fabrics are distinguishable by touch.','这两种布料摸一摸就能区分。'),('The distant tower was barely distinguishable from the grey sky.','远处的塔几乎融进灰色天空，勉强才能看出来。'),sources=[K('distinguishable'),S('indistinguishable'),O('distinguishable')]),
E('indistinguishable','/ˌɪndɪˈstɪŋɡwɪʃəbəl/','无法区分的；难以辨认的','两个东西摆在面前，却找不到能把它们分开的线索。也可能是对象和背景混在一起，根本看不出来。','否定 in- + distinguishable，英语组合；不是 in-“在里面”。',A(DW,'英语 in- + distinguishable → indistinguishable','无法辨出区别或形状'),'indistinguishable from the original 是与原件难以区分；virtually indistinguishable 是几乎分不出来。通常说明观察条件下的结果，不等于两件东西在所有层面完全相同。','indistinguishable from；almost indistinguishable；visually indistinguishable。','identical 直接断言相同；indistinguishable 强调分辨不出。更精细的方法仍可能发现差异。',('On the screen, the two shades looked indistinguishable.','在屏幕上，这两种色调看起来分不出区别。'),('The recording is almost indistinguishable from a live performance.','这段录音听起来几乎和现场演出没有区别。'),sources=[S('indistinguishable'),K('indistinguishable'),O('indistinguishable')]),
E('distinct','/dɪˈstɪŋkt/','不同的、独立的；清楚明显的','两样东西边界清楚，没有糊成一团：可以是两个不同问题，也可以是夜里清楚的一声敲门。','远接拉丁 distinguere 的分词 distinctus。词源分析包括直接拉丁借入，也有经古法语 distincter、英语旧动词 distincten 的路线；不是现代 distinguish 删去一截得到的。',DT,'two distinct issues 是两个应分开处理的问题；a distinct sound 是能清楚听见的声音。a distinct possibility 表示确实存在、不能忽略的可能性。','distinct from；two distinct types；a distinct advantage；a distinct possibility。','distinct 强调分得开或很清楚；distinctive 强调本身有特征、容易认出。声音很清楚可以 distinct，却未必独特。',('The report addresses two distinct problems.','报告讨论了两个不同的问题。'),('I heard three distinct knocks at the door.','我清楚地听到了三下敲门声。'),sources=[S('distinct'),M('distinct'),K('distinct')]),
E('distinctly','/dɪˈstɪŋktli/','清楚地；明显地；确实有某种感觉地','把程度提亮：记忆不是隐约的，而是清清楚楚；气氛不是稍有变化，而是明显不同。','distinct + -ly，英语副词。保留 distinct 的“清楚、能分开”核心。',A(DT,'英语 distinct + -ly → distinctly','清楚可辨地；明显地'),'distinctly remember 是清楚记得；distinctly different 是明显不同；distinctly uncomfortable 是明显不自在。','distinctly remember；hear distinctly；distinctly different；distinctly uneasy。','distinctively 强调独有风格；distinctly 强调清楚或程度明显。distinctly modern 是明显现代，distinctively modern 可突出有辨识度的现代风格。',('I distinctly remember leaving the keys on the table.','我清楚地记得把钥匙放在了桌上。'),('The second proposal is distinctly more practical.','第二份提案明显更实用。'),sources=[K('distinctly'),M('distinct'),O('distinctly')]),
E('distinctive','/dɪˈstɪŋktɪv/','有特色的；有辨识度的','一个特点像标记，让人一看、一听就知道是谁或是哪一种东西。重点是认得出来，未必漂亮或优越。','经古法语 distinctif 或中世纪拉丁 distinctivus，远接 distinguere 的分词词干 distinct-。现代可对应 distinct 与 -ive，但它有独立借入路线。',DV,'a distinctive voice 是一听就能认出的声音；a distinctive smell 可能好闻，也可能难闻；distinctive design 是有自己特征的设计。','a distinctive feature；a distinctive style；a distinctive voice；distinctive markings。','unique 严格说独一无二；distinctive 只要求足够有特点。distinct 则常表示清楚、彼此不同。',('The singer has a distinctive voice that is easy to recognize.','这位歌手的嗓音很有辨识度，很容易认出来。'),('A red stripe gives the packaging its distinctive look.','一道红色条纹让包装有了鲜明的特色。'),sources=[S('distinctive'),K('distinctive'),O('distinctive')]),
E('distinctively','/dɪˈstɪŋktɪvli/','有特色地；带有鲜明辨识度地','描述一种呈现方式：颜色、声音、造型带着自己的标记，让人不容易认错。','distinctive + -ly，英语副词；不是 distinct + -ly 的另一种拼法。',A(DV,'英语 distinctive + -ly → distinctively','以富于辨识度的方式'),'distinctively shaped 是形状有特色；distinctively local 是有鲜明当地特点。它可以修饰 shaped、designed，也可以修饰描述风格的词。','distinctively shaped；distinctively designed；a distinctively local style。','distinctly 意为清楚或明显；distinctively 意为有可识别的特色。两者有时都译成“鲜明地”，英文关注点不同。',('The bottles are distinctively shaped so customers can recognize them quickly.','这些瓶子的外形很有特色，顾客很快就能认出来。'),('Her work combines modern materials with a distinctively local style.','她的作品把现代材料和鲜明的地方风格结合在一起。'),sources=[K('distinctively'),S('distinctive'),O('distinctively')]),
E('distinctiveness','/dɪˈstɪŋktɪvnəs/','独特性；辨识度','把“哪里认得出它”当成一项特点来讨论：一条老街、一个品牌、一位作家，为什么不会与别人混淆。','distinctive + -ness，英语性质名词；不是“区别这件事”，而是具有特色的程度或性质。',A(DV,'英语 distinctive + -ness → distinctiveness','使某物容易与别的区分开的特色'),'preserve the distinctiveness of a place 是保留地方特色；brand distinctiveness 是品牌辨识度。独特并不自动等于质量好。','cultural distinctiveness；brand distinctiveness；preserve distinctiveness。','distinction 可指差别、区分或荣誉；distinctiveness 专说有辨识度的特点。',('The renovation preserved the distinctiveness of the old neighbourhood.','改造保留了老街区原有的特色。'),('The logo lost much of its distinctiveness when every competitor used similar colours.','当所有竞争者都使用相似颜色时，这个标志就失去了不少辨识度。'),sources=[K('distinctiveness'),S('distinctive'),O('distinctiveness')]),
E('distinction','/dɪˈstɪŋkʃən/','区别、区分；卓越；优等、荣誉','先是在两样东西之间画清界线；再从人群里画出表现出色者，于是又有卓越、优等的意思。','借古法语 distinction 或拉丁 distinctio、distinctionem，接 distinguere 的分词词干 distinct-。现代可与 distinct 对照，但不是英语 distinguish 加 -ion 的机械变形。',D+[['拉丁 distinctio／distinctionem → 古法语 distinction','分开、作区分；差异'],['英语 distinction','区分和差别；后来也指卓越、荣誉']],'make a distinction between 是作区分；a person of distinction 是卓越人物；pass with distinction 表示以优异等级通过，具体等级由制度决定。','draw a distinction；a distinction between；with distinction；a writer of distinction。','difference 可只是差异事实；distinction 常涉及如何划分或辨别。with distinction 的荣誉义不能译成“带着区别”。',('We need to draw a distinction between an error and deliberate deception.','我们需要区分无意犯错与故意欺骗。'),('She completed the course with distinction.','她以优异成绩完成了课程。'),('The museum makes no distinction between local and visiting artists.','博物馆对本地艺术家与来访艺术家一视同仁。'),sources=[S('distinction'),K('distinction'),O('distinction')]),
E('indistinct','/ˌɪndɪˈstɪŋkt/','模糊的；不清楚的','轮廓、声音或记忆糊在一起，边界还在，却看不清、听不真。','拉丁 in- + distinctus 形成 indistinctus，借入英语，也有法语 indistinct 中介分析。现代可按否定 in- + distinct 理解。',IND,'an indistinct outline 是模糊轮廓；indistinct speech 是听不清的话；an indistinct memory 是不清晰的记忆。','an indistinct shape；an indistinct voice；an indistinct memory。','indistinguishable 常说两者分不出区别；indistinct 说单个形象、声音本身不清晰。',('Only an indistinct outline of the hill was visible through the mist.','透过薄雾，只能看见山丘模糊的轮廓。'),('His reply was too indistinct for anyone to understand.','他的回答含混不清，谁也没听明白。'),sources=[S('indistinct'),K('indistinct'),O('indistinct')]),
E('indistinctly','/ˌɪndɪˈstɪŋktli/','模糊地；含混不清地','信息传来了，却像隔了一层雾：你听见有人说话，仍抓不住具体字句。','现代可拆 indistinct + -ly，也有 in- + distinctly 的分析。早期副词还曾表示不加区别地，不应把它的全部历史硬放到现代形容词词义之后。',D+[['拉丁 distinctus、indistinctus 的区分／不区分词族','提供相关词基'],['英语 in- + distinctly／indistinct + -ly → indistinctly','早期有不加区别义；现代常为模糊、含混地']],'speak indistinctly 是口齿或声音不清；remember indistinctly 是记得模模糊糊。它不一定说明音量小，也可能是发音含混。','speak indistinctly；hear indistinctly；remember indistinctly。','quietly 指音量低或安静；indistinctly 指不清楚。一个人说得很响，仍可能含混。',('Someone spoke indistinctly at the back of the room.','房间后面有人含混不清地说了句话。'),('I remember the journey only indistinctly.','那次旅程我只记得模模糊糊。'),sources=[K('indistinctly'),S('indistinct'),M('indistinct')]),
E('extinguish','/ɪkˈstɪŋɡwɪʃ/','扑灭、熄灭；使消失','让正在燃烧的火停下来；借这个画面，也可以说希望、热情或某种权利被彻底消除。','借拉丁 exstinguere、extinguere“扑灭”，ex- 表示向外、消去，英语词尾按 -ish 类形式适应。它和 distinguish 的更远关系有争议，本词从明确的“扑灭”义开始记。',X,'extinguish a fire 是扑灭火；extinguish hope 是让希望破灭。法律文本可说 extinguish a right，指权利消灭，这只是词义，不是一个统一的法律程序。','extinguish a fire；extinguish the flames；extinguish hope。','put out 是日常常用说法；extinguish 较正式。火已灭与从未起火是两回事。',('Firefighters extinguished the flames before they reached the next building.','消防员在火焰蔓延到下一栋楼前将其扑灭。'),('The rejection did not extinguish her enthusiasm for the project.','这次拒绝没有浇灭她对项目的热情。'),sources=[S('extinguish'),K('extinguish'),M('extinguish')]),
E('extinguisher','英 /ɪkˈstɪŋɡwɪʃə/；美 /ɪkˈstɪŋɡwɪʃər/','灭火器；熄灭某物的装置','extinguish 是把火灭掉，-er 把这个动作交给一件器具：能够用于扑灭火的设备。','extinguish + -er，英语动作名词；常见完整说法 fire extinguisher，语境清楚时省去 fire。',A(X,'英语 extinguish + -er → extinguisher','用于熄灭的器具，常指灭火器'),'在公共场所标志、设备清单中，extinguisher 通常就是灭火器。这个词只告诉你设备用途，不说明具体类型或适用火种。','a fire extinguisher；an extinguisher cabinet；inspect an extinguisher。','firefighter 是消防员；extinguisher 通常是设备。两者都与灭火有关，-er 在这里不表示人。',('A fire extinguisher is mounted beside the exit.','出口旁安装着一具灭火器。'),('The inspection record lists every extinguisher in the building.','检查记录列出了楼里的每一具灭火器。'),sources=[K('extinguisher'),M('extinguisher'),O('extinguisher')]),
E('extinct','/ɪkˈstɪŋkt/','灭绝的；不复存在的；死的〔火山〕','原来的火已经没有了，再延伸为一个物种、家族或传统不再延续。物种灭绝意味着没有存活个体，不只是数量稀少。','拉丁 exstinguere 的分词 exstinctus、extinctus 借入英语。不是英语 extinguish 的规则过去式；最早的熄灭意象后来用于物种等。',X[:1]+[['拉丁分词 exstinctus／extinctus → 英语 extinct','被扑灭的；后指已消失、已灭绝的']],'an extinct species 是灭绝物种；an extinct volcano 是通常认为不再会喷发的死火山。科技或社会评论也可借指一种不复存在的做法。','an extinct species；become extinct；an extinct volcano；now extinct。','endangered 是濒危，仍有存活个体；extinct 是已灭绝。火山 dormant 是休眠，不能直接等同 extinct。',('The display includes models of several extinct animals.','展览中有几种已灭绝动物的模型。'),('This once common custom is now almost extinct.','这种过去很普遍的习俗现在几乎消失了。'),sources=[S('extinct'),K('extinct'),O('extinct')]),
E('extinction','/ɪkˈstɪŋkʃən/','灭绝、消亡；消除；〔心理学〕消退','关注从仍然存在到不再延续的过程或状态。生态语境是物种消失，其他领域会把“原来持续的东西停止”用于自己的专门含义。','来自拉丁 extinctio、extinctionem，接 exstinguere 的分词词干；它是独立借入的名词，不是必须先有英语 extinct 再造出来。',X[:1]+[['拉丁分词词干 extinct- → extinctio／extinctionem','熄灭、消除的过程或结果'],['英语 extinction','灭绝、消亡；各领域的消退义']],'risk of extinction 是灭绝风险；mass extinction 是大规模物种灭绝。学习心理学中的 extinction 是已习得反应在特定条件变化后减弱，不等于记忆被彻底擦掉。','face extinction；on the brink of extinction；mass extinction；the extinction of a tradition。','extinct 是形容词，extinction 是名词。local extinction 是某地消失，不必然代表整个物种在全球灭绝。',('Habitat loss has pushed the species closer to extinction.','栖息地丧失使这个物种更接近灭绝。'),('The archive documents the gradual extinction of several local crafts.','档案记录了几种地方手艺逐渐消失的过程。'),sources=[S('extinction'),K('extinction'),O('extinction'),'https://learnmem.cshlp.org/content/11/5/485.full']),
E('instinct','/ˈɪnstɪŋkt/','本能；直觉；自然的倾向','像身体里有一股推动力，不必先列出理由，就让你朝某个方向反应。日常也指经验形成的直觉，不一定真是与生俱来。','来自拉丁 instinctus“推动、冲动”，接 instinguere“激起、驱使”，经法语或直接借入。这里 in- 是向内，不是否定“没有”。',I,'survival instinct 是生存本能；my first instinct 是第一反应；an instinct for business 是做生意的敏锐感觉。直觉有用，却不是事实已经证实。','by instinct；trust your instincts；your first instinct；an instinct for。','instinct 通常先于有意识推理；habit 是重复形成的习惯。日常口语会有交叉，不宜仅凭这个词判断一个行为一定天生。',('My first instinct was to protect the child from the crowd.','我的第一反应是护住孩子，不让人群挤到他。'),('She has an instinct for finding the right question to ask.','她很善于凭直觉找到该问的关键问题。'),('His instincts told him to check the figures again.','直觉告诉他应该再核对一次数字。'),sources=[S('instinct'),K('instinct'),O('instinct')]),
E('instinctive','/ɪnˈstɪŋktɪv/','本能的；不假思索的；自然产生的','反应快过了有意识的盘算：手先伸过去接住东西，之后才意识到自己做了什么。','可按 instinct + -ive 理解，也有从拉丁分词词干 instinct- 加 -ive 的分析。不要把它说成一个已经查明的拉丁 instinctivus 借词。',IV,'an instinctive reaction 是自发反应；an instinctive dislike 是说不清理由就产生的反感。熟练技能也可被日常语言称为 instinctive，不代表训练完全没作用。','an instinctive response；an instinctive dislike；instinctive behaviour。','instinctual 也表示与本能有关，较常用于本能冲动的讨论；instinctive 广泛描述自然、立即的反应，二者并无绝对界线。',('She made an instinctive move to catch the falling glass.','她本能地伸手去接掉下来的杯子。'),('His instinctive dislike of the idea softened after he heard the details.','听完细节后，他最初对这个主意的直觉性反感减轻了。'),sources=[S('instinctive'),K('instinctive'),M('instinctive')]),
E('instinctively','/ɪnˈstɪŋktɪvli/','本能地；不假思索地','还没想好理由，动作或感觉就先发生了；也常描述练熟后几乎自动出现的反应。','现代结构是 instinctive + -ly。已有词史把副词的书面记录列得早于独立形容词；这不影响结构分析，但不能据此画成确定年代的先形容词、后副词。',I[:2]+[['英语 instinct- 一族与 -ive、-ly 构词','形容词、副词的最早记录并不必然按结构先后出现'],['英语 instinctively','本能地、自然地；现代对应 instinctive + -ly']],'react instinctively 是不经思考就反应；instinctively know 是直觉上觉得明白。后者是说话人的把握感，不是知识证据。','react instinctively；move instinctively；instinctively feel；almost instinctively。','automatically 还可指机器或规则自动运行；instinctively 常带生物本能、人的直觉或熟练反应的色彩。',('She instinctively stepped back when the door swung open.','门突然打开时，她本能地退了一步。'),('After years of practice, he adjusted the balance almost instinctively.','多年练习后，他几乎不假思索就能调整平衡。'),sources=[S('instinctive'),K('instinctively'),O('instinctively')]),
E('instinctual','/ɪnˈstɪŋktʃuəl/','本能的；与本能驱动有关的','把注意力放在行为背后的自然驱动上，例如寻求安全、寻找食物，而不是一步步有意识规划。','instinct + -ual，英语形容词。常用读法中 /t/ 与后面的音合成 /tʃ/，听起来像“ch”；也有保留 /tj/ 的读法。',A(I,'英语 instinct + -ual → instinctual','属于本能或受本能驱动的'),'instinctual drives 指本能驱力；instinctual behaviour 指与本能相关的行为。心理学、行为讨论中较常见，但具体行为仍可能同时受学习与环境影响。','instinctual drives；instinctual behaviour；an instinctual response。','instinctive 与 instinctual 大量重叠。前者日常更常形容不假思索的反应，后者更容易出现在讨论本能动力的语境。',('The essay explores instinctual drives and the rules that restrain them.','文章讨论了本能驱力及约束它们的规则。'),('The researcher warned against describing every repeated action as instinctual.','研究者提醒，不应把每一种反复出现的动作都称为本能行为。'),sources=[K('instinctual'),M('instinctual'),O('instinctual')]),
]
ROOT=dict(id='C1427',meaning='区分、标出；另有扑灭与激起支线',core='这一组不能只背一个“分开”。distinguere 是分开、标出区别；exstinguere 是扑灭；instinguere 是激起、驱使。它们更早的刺、推等联系有词源争议，先掌握有记录的拉丁意义。',image='辨别支线：distinguish → 能区分或认不清；分词 distinct- → 差异、特色。扑灭支线：extinguish → extinct、extinction。激起支线：instinct → 自然的内在反应。',intro='学习重点是 distinct、distinctive、distinguished 的区别，以及 instinct 与 extinct 这两个看着很像、意思却差很远的词。用各自的拉丁动词作起点，比硬编一个故事更容易记牢。',forms='distinguere 的分词 distinctus 提供 distinct-；exstinguere 的分词 exstinctus 提供 extinct-；instinguere 的 instinctus 提供 instinct-。原表 apart 对应 dis- 前缀，不能直接当成 stingu- 的唯一意思。更早语义连接有刺、推等不同解释，不把其中一种当定论。',branches=[['辨别与出众','distinguish, distinguished, distinguishable, indistinguishable'],['清楚、特色与模糊','distinct, distinctly, distinctive, distinctively, distinctiveness, distinction, indistinct, indistinctly'],['熄灭与消亡','extinguish, extinguisher, extinct, extinction'],['内在驱动与自然反应','instinct, instinctive, instinctively, instinctual']],contrasts='distinct 是清楚、彼此不同；distinctive 是有辨识度；distinguished 常赞成就或气度。extinct 是灭绝，instinct 是本能；重音也不同：extinct 重后，instinct 名词重前。',practice='A distinctive voice is easy to distinguish. 有特色的声音容易辨认。再说：The species is extinct, but its behaviour can still be studied in records. 物种已灭绝，但其行为仍可通过记录研究。',words=[],exclude={})
if __name__=='__main__':
 m=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text());r=next(x for x in m['roots'] if x['id']==ROOT['id']);ROOT['words']=[w for w in r['family'] if '-' not in w]
 assert set(ROOT['words'])&set(m['owned_words'])=={e['word'] for e in W}
 assert len(W)==len({e['word'] for e in W}) and all(len(e['examples'])>=2 and len(e['history'])>=2 for e in W)
 OUT.mkdir(parents=True,exist_ok=True)
 (OUT/'roots_batch200_vid_58.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2));(OUT/'words_batch200_vid_58.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
 print('stingu:',len(W),'words;',sum(len(e['examples']) for e in W),'examples;',len(ROOT['words']),'references')
